import{_ as t,o as a,c as i,ag as n}from"./chunks/framework.7BZpJk9v.js";const c=JSON.parse('{"title":"Admin guide: the first sales","description":"Run the portal from a new brand to a paid order.","frontmatter":{"description":"Run the portal from a new brand to a paid order.","search":false,"editLink":false,"prev":false,"next":false,"head":[["meta",{"name":"robots","content":"noindex, nofollow"}]]},"headers":[],"relativePath":"internal/prompts/admin-guide.md","filePath":"internal/prompts/admin-guide.md"}'),r={name:"internal/prompts/admin-guide.md"};function s(l,e,o,d,h,m){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="admin-guide-the-first-sales" tabindex="-1">Admin guide: the first sales <a class="header-anchor" href="#admin-guide-the-first-sales" aria-label="Permalink to &quot;Admin guide: the first sales&quot;">​</a></h1><p>What you need to know to run the portal for the first sales. The flow: create the brand, upload its media and site, invite the brand, the brand selects, and they may invite their team.</p><h2 id="_1-set-up-the-brand" tabindex="-1">1. Set up the brand <a class="header-anchor" href="#_1-set-up-the-brand" aria-label="Permalink to &quot;1. Set up the brand&quot;">​</a></h2><ul><li>Create the brand in Admin, Clients.</li><li>Upload its media in Admin, Media (<a href="./media-zip.html">Brand media ZIP</a>).</li><li>Upload its site in Admin, Sites (<a href="./website.html">Brand website</a>). The brand sees only the version you mark <strong>Show To Brand</strong>.</li><li>Check the prices before you invite anyone: <ul><li>Admin, Kits, <strong>Kit Prices</strong> sets the prices for all brands.</li><li><strong>Custom Prices</strong> on the brand page sets prices for that brand only.</li><li><strong>Deal Desk</strong> adds discounts.</li></ul></li><li>Use <strong>Viewing As</strong> on the brand page to see the portal as the brand sees it. In that view, Confirm saves nothing and sends no email.</li></ul><h2 id="_2-invite-the-brand" tabindex="-1">2. Invite the brand <a class="header-anchor" href="#_2-invite-the-brand" aria-label="Permalink to &quot;2. Invite the brand&quot;">​</a></h2><ul><li>Go to the brand page, People, <strong>Invite Someone</strong>. Use <strong>Resend Invite</strong> if they lose the email.</li><li>You do not need <strong>Convert To Lead</strong>. It sends the same invite and also records &quot;Intro Call Held&quot;. Use it only when you had the intro call and want the Pipeline to show that.</li><li>If the invite email is set to Draft For Approval, it waits in Admin, Emails, Drafts until someone approves it.</li><li>Invite real brands only from live. Staging never emails real clients.</li></ul><h2 id="_3-their-team" tabindex="-1">3. Their team <a class="header-anchor" href="#_3-their-team" aria-label="Permalink to &quot;3. Their team&quot;">​</a></h2><ul><li>The brand can invite teammates from its Team page.</li><li>A teammate with the same email domain as the owner joins at once.</li><li>A teammate with a different domain waits until you click <strong>Approve</strong> on the brand page, People.</li><li>Any teammate who has joined can confirm a selection.</li></ul><h2 id="_4-when-they-select" tabindex="-1">4. When they select <a class="header-anchor" href="#_4-when-they-select" aria-label="Permalink to &quot;4. When they select&quot;">​</a></h2><ul><li>Nothing is signed or paid in the portal. The brand clicks <strong>Confirm My Selection</strong> and gets an email.</li><li>The email promises a <strong>document signature request and a payment link, usually within one business day</strong>. Keeping that promise is our job.</li><li>We get a Slack post with the full breakdown (kits, add-ons, amounts, their note), an alert email and a Today item.</li><li>A new selection replaces and cancels the earlier one. The Slack post shows &quot;Replaces&quot;. Always use the latest selection.</li><li>Send the agreement and the payment link yourself.</li><li>When the money arrives, go to Admin, Orders and click <strong>Mark Paid</strong>. It needs a reference and a reason.</li><li>If the deal falls through, click <strong>Cancel</strong> in Admin, Orders.</li></ul><h2 id="_5-small-things" tabindex="-1">5. Small things <a class="header-anchor" href="#_5-small-things" aria-label="Permalink to &quot;5. Small things&quot;">​</a></h2><ul><li>After a portal release, reload any open portal tab. An open tab keeps running the old version.</li><li>The brand guide PDFs still say that brands sign in the portal. Ignore that for now.</li></ul>',12)])])}const p=t(r,[["render",s]]);export{c as __pageData,p as default};
